const csv = $input.first().json.data;
const linhas = String(csv).trim().split('\n');
const header = linhas[0].split(',').map(h => h.trim());
return linhas.slice(1).filter(l => l.trim() !== '').map(linha => {
  const cols = linha.split(',');
  const item = {};
  header.forEach((h, i) => { item[h] = (cols[i] || '').trim(); });
  return { json: item };
});

const itens = $input.all();

const mapa = new Map();
for (const item of itens) {
  const j = item.json;
  const clientes = (j.body && Array.isArray(j.body.clientes)) ? j.body.clientes : [];
  const investimento = j.produto ? {
    perfil: j.perfil,
    produto: j.produto,
    minimo: j.minimo,
    rentabilidade: j.rentabilidade,
  } : null;

  for (const c of clientes) {
    if (!mapa.has(c.email)) {
      mapa.set(c.email, {
        nome: c.nome,
        email: c.email,
        saldo: c.saldo,
        perfil: c.perfil,
        investimentos: [],
      });
    }
    if (investimento) mapa.get(c.email).investimentos.push(investimento);
  }
}

const resultado = [];
for (const c of mapa.values()) {
  const recomendados = c.investimentos.filter(i => i.perfil === c.perfil);
  const linhas = recomendados
    .map(i => `- ${i.produto} (aporte minimo: R$ ${i.minimo}, rentabilidade: ${i.rentabilidade})`)
    .join('\n');
  const mensagem =
    `Ola, ${c.nome}! Seu perfil de investidor e ${c.perfil} e seu saldo atual e ${c.saldo}.\n` +
    `Com base no seu perfil, separamos as seguintes opcoes:\n${linhas}\n` +
    `Conte conosco para investir melhor!`;

  resultado.push({
    json: {
      nome: c.nome,
      email: c.email,
      perfil: c.perfil,
      saldo: c.saldo,
      recomendados,
      mensagem,
    },
  });
}

return resultado;

const MOTIVOS = {
  Conservador: 'Perfil conservador: prioriza seguranca, liquidez e baixa exposicao a risco.',
  Moderado: 'Perfil moderado: busca equilibrio entre seguranca e rentabilidade.',
  Arrojado: 'Perfil arrojado: aceita maior risco em busca de retornos mais altos.',
};

const COPY_RULES = 'Tom consultivo e cordial; frases curtas; nao prometer rentabilidade; destacar seguranca, liquidez e diversificacao; encerrar com convite a acao.';

function parseSaldo(valor) {
  if (typeof valor === 'number') return valor;
  const limpo = String(valor).replace(/[^0-9,.-]/g, '');
  const normalizado = limpo.replace(/\./g, '').replace(',', '.');
  const numero = parseFloat(normalizado);
  return isNaN(numero) ? null : numero;
}

const tabela = $input.all().map((item) => {
  const j = item.json;
  const recomendados = Array.isArray(j.recomendados) ? j.recomendados : [];
  return {
    json: {
      email: j.email,
      nome: j.nome,
      perfil: j.perfil,
      saldo: j.saldo,
      extra: recomendados
        .map(r => `${r.produto} (minimo: R$ ${r.minimo}, rentabilidade: ${r.rentabilidade})`)
        .join('; '),
      saldo_num: parseSaldo(j.saldo),
      recomendacao: recomendados.map(r => r.produto).join('; '),
      motivo: MOTIVOS[j.perfil] || 'Recomendacao alinhada ao perfil do cliente.',
      mensagem_base: j.mensagem,
      copy_rules: COPY_RULES,
    },
  };
});

tabela.sort((a, b) => (a.json.perfil + a.json.nome).localeCompare(b.json.perfil + b.json.nome));

return tabela;

const itens = $input.all();

function normalizarEmail(valor) {
  let email = String(valor || '').trim().toLowerCase();
  const match = email.match(/<([^>]+)>/);
  if (match) email = match[1];
  email = email.replace(/^mailto:/, '').replace(/\s+/g, '');
  return email;
}

function emailValido(email) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email);
}

function normalizarTexto(valor) {
  return String(valor || '')
    .replace(/\r\n/g, '\n')
    .replace(/\r/g, '\n')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .replace(/\*\*(.*?)\*\*/g, '$1')
    .replace(/[*_`#]/g, '')
    .replace(/[ \t]{2,}/g, ' ')
    .trim();
}

function normalizarPerfil(valor) {
  const p = String(valor || '').trim().toLowerCase();
  if (p.startsWith('conserv')) return 'Conservador';
  if (p.startsWith('moder')) return 'Moderado';
  if (p.startsWith('arroj')) return 'Arrojado';
  return String(valor || '').trim();
}

function normalizarNome(valor) {
  return String(valor || '')
    .trim()
    .replace(/\s+/g, ' ')
    .replace(/\b\w/g, (c) => c.toUpperCase());
}

const baseItens = $('Code in JavaScript2').all();

return itens.map((item, i) => {
  const gemini = item.json || {};
  const base = (baseItens[i] && baseItens[i].json) || {};
  const email = normalizarEmail(base.email);
  const nome = normalizarNome(base.nome);
  const mensagem = normalizarTexto(gemini.mergedResponse || gemini.text || base.mensagem_base || '');
  const valido = emailValido(email);

  return {
    json: {
      email,
      nome,
      perfil: normalizarPerfil(base.perfil),
      saldo: base.saldo,
      assunto: 'Sua recomendacao de investimento, ' + nome,
      mensagem,
      email_valido: valido,
      erro: valido ? null : 'E-mail invalido ou ausente',
    },
  };
});
